export function storeConfig(data) {
  const value = data.storefront || {};
  return {
    sections: storeSections
      .map((s, i) => ({
        ...s,
        visible: !s.hiddenByDefault,
        order: i + 1,
        ...(value.sections || []).find((v) => v.id === s.id),
      }))
      .sort((a, b) => a.order - b.order),
    featuredCourseIds: value.featuredCourseIds || [],
    featuredInstructorIds: value.featuredInstructorIds || [],
    foundation:
      value.foundation ||
      "شرح المفاهيم من البداية، وفهم العلاقات وطريقة الحل قبل الانتقال إلى مسائل أكثر تنوعًا.",
    training:
      value.training ||
      "تطبيق على المهارات، والتعامل مع أنماط متنوعة من الأسئلة، ثم الاختبارات والمراجعة.",
    faq: value.faq || faq,
    supportEmail: value.supportEmail || "",
  };
}
